INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(33811, 'Matthew 10:40', 'Matthew', 10, 40, 'څوک چې تاسو قبول کړي، نو زه یې قبول کړی یم او څوک چې ما قبول کړي، نو هغه څوک یې قبول کړی دی چې زه یې رالېږلی یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_40.mp3', '', 1761754199, 1761754199),
(33812, 'Matthew 10:41', 'Matthew', 10, 41, 'هرڅوک چې یو پیغمبر په دې خاطر قبول کړي چې هغه پیغمبر دی، نو هغه به د یو پیغمبر اجر ومومي او څوک چې یو نېک سړی په دې خاطر قبول کړي چې هغه نېک سړی دی، نو هغه به د نېک سړي اجر ومومي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_41.mp3', '', 1761754199, 1761754199),
(33813, 'Matthew 10:42', 'Matthew', 10, 42, 'هرڅوک چې د دې عادي خلکو څخه یوه ته په دې خاطر چې هغه زما د پیروانو څخه دی، یوه پیاله یخې اوبه هم ورکړي، نو په یقین سره زه تاسو ته دا وایم چې هغه سړی به بې‌اجره پاتې نه شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew10_verse_42.mp3', '', 1761754199, 1761754199),
(33814, 'Luke 6:1', 'Luke', 6, 1, 'د سبت په یوه ورځ عیسی د خپلو شاګردانو سره د غنمو په پټیو تېرېده. شاګردانو یې د غنمو وږي راشکول او په لاسونو کې یې موږل او خوړل یې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_1.mp3', '', 1761754199, 1761754199),
(33815, 'Luke 6:2', 'Luke', 6, 2, 'ځینو فریسیانو پوښتنه وکړه: «تاسو ولې داسې کار کوئ چې د سبت په ورځ ناروا دی؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_2.mp3', '', 1761754199, 1761754199),
(33816, 'Luke 6:3', 'Luke', 6, 3, 'عیسی هغوی ته په ځواب کې وویل: «ایا تاسو دا نه دي لوستلي کله چې داود او ملګري یې وږي شوي وو، نو هغه څه وکړل؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_3.mp3', '', 1761754199, 1761754199),
(33817, 'Luke 6:4', 'Luke', 6, 4, 'هغه د خدای کور ته ننوت، سپېڅلې ډوډۍ یې راواخیستله او ویې خوړه او خپلو ملګرو ته یې هم ورکړه، که څه هم د هغې ډوډۍ خوړل له کاهنانو پرته بل چاته روا نه وو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_4.mp3', '', 1761754199, 1761754199),
(33818, 'Luke 6:5', 'Luke', 6, 5, 'بیا عیسی وویل: «د انسان زوی د سبت د ورځې خاوند هم دی.» عیسی د سبت په ورځ ناروغانو ته شفا ورکوي (متي ۱۲‏:‌۹‌‏-‌۱۴ او مرقوس ۳‏:‌۱‌‏-‌۶)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_5.mp3', '', 1761754199, 1761754199),
(33819, 'Luke 6:6', 'Luke', 6, 6, 'د بل سبت په ورځ عیسی کنیسې ته ننوت او تعلیم یې ورکاوه. هلته یو سړی ؤ چې ښي لاس یې وچ شوی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_6.mp3', '', 1761754199, 1761754199),
(33820, 'Luke 6:7', 'Luke', 6, 7, 'د شریعت ځینو عالمانو او فریسیانو په ځیر سره هغه ته کتل چې وویني ایا عیسی به د سبت په ورځ چاته شفا ورکوي که نه، ترڅو په هغه باندې د تور لګولو دپاره یو دلیل پیدا کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_7.mp3', '', 1761754199, 1761754199),
(33821, 'Luke 6:8', 'Luke', 6, 8, 'عیسی د هغوی په فکرونو پوه شو او هغه سړي ته چې لاس یې وچ شوی ؤ وویل: «راپاڅېږه او د ټولو په مخکې ودرېږه.» نو هغه راپاڅېد او هلته ودرېده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_8.mp3', '', 1761754199, 1761754199),
(33822, 'Luke 6:9', 'Luke', 6, 9, 'بیا عیسی هغوی ته وویل: «زه ستاسو څخه پوښتنه کوم: ایا د سبت په ورځ نېکي کول روا دي که بدي کول؟ د یو چا ژوند ژغورل، که له منځه وړل؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_9.mp3', '', 1761754199, 1761754199),
(33823, 'Luke 6:10', 'Luke', 6, 10, 'عیسی ګردچاپېره هغوی ټولو ته وکتل او بیا یې هغه سړي ته وویل: «خپل لاس دې وغزوه.» هغه خپل لاس وغزاوه او لاس یې روغ شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_10.mp3', '', 1761754199, 1761754199),
(33824, 'Luke 6:11', 'Luke', 6, 11, 'خو د شریعت عالمان او فریسیان ډېر په قهر شول او یو بل ته یې وویل چې د عیسی سره څه وکړو. عیسی د خپلو شاګردانو څخه دولس رسولان ټاکي (متي ۱۰‏:‌۱‌‏-‌۴ او مرقوس ۳‏:‌۱۳‌‏-‌۱۹)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_11.mp3', '', 1761754199, 1761754199),
(33825, 'Luke 6:12', 'Luke', 6, 12, 'په هغو ورځو کې عیسی د دعا دپاره غره ته لاړ او ټوله شپه یې خدای ته په دعا کولو تېره کړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_12.mp3', '', 1761754199, 1761754199),
(33826, 'Luke 6:13', 'Luke', 6, 13, 'کله چې سهار شو، نو خپل شاګردان یې راوغوښتل او د هغوی له منځ نه یې دولس تنه غوره کړل او هغوی یې د رسولانو په نوم یاد کړل:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_13.mp3', '', 1761754199, 1761754199),
(33827, 'Luke 6:14', 'Luke', 6, 14, 'شمعون چې عیسی ورباندې پطروس نوم کېښود او د هغه ورور اندریاس، یعقوب، یوحنا، فیلیپوس او بارتولما،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_14.mp3', '', 1761754199, 1761754199),
(33828, 'Luke 6:15', 'Luke', 6, 15, 'متي، توما، یعقوب د حلفي زوی او شمعون چې په سرتېري مشهور ؤ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_15.mp3', '', 1761754199, 1761754199),
(33829, 'Luke 6:16', 'Luke', 6, 16, 'او یهودا د یعقوب زوی او یهودا اسخریوتي چې وروسته خاین شو. عیسی خلکو ته تعلیم او شفا ورکوي (متي ۴‏:‌۲۳‌‏-‌۲۵)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_16.mp3', '', 1761754199, 1761754199),
(33830, 'Luke 6:17', 'Luke', 6, 17, 'عیسی د خپلو رسولانو سره د غره څخه راښکته شو او په یو هوار ځای کې ودرېده. په هغه ځای کې د هغه د پیروانو یوه لویه ډله او د ټولې یهودیې، اورشلیم او د صور او صیدون د ساحلي ښارونو څخه ګڼ شمېر خلک موجود وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_17.mp3', '', 1761754199, 1761754199),
(33831, 'Luke 6:18', 'Luke', 6, 18, 'دا خلک د دې دپاره راغلي وو چې د هغه خبرې واوري او د خپلو ناروغیو څخه روغ شي. همدارنګه هغه خلک چې پېریانو نیولي وو هم راغلي وو او روغ شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_18.mp3', '', 1761754199, 1761754199),
(33832, 'Luke 6:19', 'Luke', 6, 19, 'ټولو خلکو کوښښ کاوه چې عیسی ته لاس وروړي، ځکه چې د هغه څخه به یو قدرت راوته او ټول به یې روغول. خوشحالي او غم (متي ۵‏:‌۱‌‏-‌۱۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_19.mp3', '', 1761754199, 1761754199),
(33833, 'Luke 6:20', 'Luke', 6, 20, 'بیا عیسی خپلو شاګردانو ته مخ راواړاوه او ویې ویل: «بختور یئ تاسو چې اوس غریبان یئ، ځکه چې د خدای پاچاهي ستاسو ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_20.mp3', '', 1761754199, 1761754199),
(33834, 'Luke 6:21', 'Luke', 6, 21, 'بختور یئ تاسو چې اوس وږي یئ، ځکه چې تاسو به ماړه شئ. بختور یئ چې اوس ژاړئ، ځکه چې تاسو به وخاندئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_21.mp3', '', 1761754199, 1761754199),
(33835, 'Luke 6:22', 'Luke', 6, 22, 'بختور یئ تاسو چې خلک درڅخه د انسان د زوی په خاطر کرکه کوي او خپل منځ کې مو نه پرېږدي، سپکاوی درته کوي او تاسو بدناموي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_22.mp3', '', 1761754199, 1761754199),
(33836, 'Luke 6:23', 'Luke', 6, 23, 'نو په هغه وخت کې خوښي وکړئ او د خوشحالۍ ټوپونه ووهئ، ځکه چې په جنت کې به لوی اجر ولرئ. د هغوی نیکونو هم د پیغمبرانو سره همداسې چلند کړی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_23.mp3', '', 1761754199, 1761754199),
(33837, 'Luke 6:24', 'Luke', 6, 24, 'خو افسوس دې وي ستاسو شتمنو په حال! ځکه چې تاسو خپل د سوکالۍ وخت تېر کړی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_24.mp3', '', 1761754199, 1761754199),
(33838, 'Luke 6:25', 'Luke', 6, 25, 'افسوس دې وي ستاسو په حال چې اوس ماړه یئ، ځکه چې تاسو به وږي شئ افسوس دې وي په تاسو چې اوس خاندئ، ځکه چې ستاسو خندا به په ویر او ژړا بدله شي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_25.mp3', '', 1761754199, 1761754199),
(33839, 'Luke 6:26', 'Luke', 6, 26, 'افسوس دې وي ستاسو په حال کله چې ټول ستاسو صفت کوي. ځکه چې د هغوی نیکونو هم د جعلي پیغمبرانو صفت کاوه. د دښمنانو سره مینه (متي ۵‏:‌۳۸‌‏-‌۴۸، ۷‏:‌۱۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_26.mp3', '', 1761754199, 1761754199),
(33840, 'Luke 6:27', 'Luke', 6, 27, 'خو زه تاسو ته چې زما خبرې اورئ، وایم چې د خپلو دښمنانو سره مینه کوئ، څوک چې ستاسو څخه کرکه کوي د هغوی سره ښه کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_27.mp3', '', 1761754199, 1761754199),
(33841, 'Luke 6:28', 'Luke', 6, 28, 'د هغو خلکو دپاره چې په تاسو لعنت وایي، برکت وغواړئ او د هغو خلکو دپاره چې ستاسو سره بد چلند کوي، دعا وکړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_28.mp3', '', 1761754199, 1761754199),
(33842, 'Luke 6:29', 'Luke', 6, 29, 'که چېرې څوک تاته په یو مخ څپېړه درکړي، نو خپل بل مخ هم ورته ورواړوه. که څوک درڅخه چپنه واخلي، نو پرېږده چې ستا کمیس هم واخلي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_29.mp3', '', 1761754199, 1761754199),
(33843, 'Luke 6:30', 'Luke', 6, 30, 'که څوک درڅخه کوم شی وغواړي نو ورته وریې کړه او که چېرې څوک ستا څخه کوم شی چې هغه ستا وي واخلي، نو بېرته یې ورڅخه مه غواړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_30.mp3', '', 1761754199, 1761754199),
(33844, 'Luke 6:31', 'Luke', 6, 31, 'د نورو سره داسې چلند کوئ لکه څنګه چې تاسو یې د ځان دپاره د هغوی څخه غواړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_31.mp3', '', 1761754199, 1761754199),
(33845, 'Luke 6:32', 'Luke', 6, 32, 'که چېرې یوازې د هغو خلکو سره مینه کوئ چې ستاسو سره مینه کوي، نو په دې کې به ستاسو دپاره څه اجر وي؟ ځکه ګناهکاران هم د هغه چا سره مینه کوي څوک چې د هغوی سره مینه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_32.mp3', '', 1761754199, 1761754199),
(33846, 'Luke 6:33', 'Luke', 6, 33, 'که چېرې تاسو یوازې د هغو خلکو سره نېکي کوئ چې ستاسو سره نېکي کوي، نو په دې کې به ستاسو دپاره څه اجر وي؟ ځکه چې ګناهکاران هم همداسې کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_33.mp3', '', 1761754199, 1761754199),
(33847, 'Luke 6:34', 'Luke', 6, 34, 'که چېرې هغو خلکو ته پور ورکوئ چې د بېرته اخیستلو تمه یې لرئ، نو په دې کې به ستاسو دپاره څه اجر وي؟ ځکه چې ګناهکاران هم نورو ګناهکارنو ته پور ورکوي چې بېرته یې ترې پوره واخلي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_34.mp3', '', 1761754199, 1761754199),
(33848, 'Luke 6:35', 'Luke', 6, 35, 'خو تاسو د خپلو دښمنانو سره مینه کوئ او د هغوی سره نېکي کوئ. پور ورکړئ او د بېرته اخیستلو تمه ورڅخه مه کوئ. نو دا به ستاسو دپاره لوی اجر وي او تاسو به د خدای تعالی اولادونه یئ، ځکه چې هغه په ناشکره او بدکارو خلکو هم مهربانه دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_35.mp3', '', 1761754199, 1761754199),
(33849, 'Luke 6:36', 'Luke', 6, 36, 'لکه څنګه چې ستاسو اسماني پلار زړه سواندی دی، نو تاسو هم زړه سواندي اوسئ. د نورو په هکله قضاوت کول (متي ۷‏:‌۱‌‏-‌۵)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_36.mp3', '', 1761754199, 1761754199),
(33850, 'Luke 6:37', 'Luke', 6, 37, 'د نورو په هکله قضاوت مه کوئ، نو تاسو به تر قضاوت لاندې نه نیول کېږئ. نور خلک مه ملامتوئ، نو خدای به تاسو نه ملامتوي. نور خلک وبخښئ، نو خدای به تاسو وبخښي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_37.mp3', '', 1761754199, 1761754199),
(33851, 'Luke 6:38', 'Luke', 6, 38, 'نورو ته څه شی ورکړئ، نو تاسو ته به هم درکړل شي. تاسو ته به په ډکې پیمانې، په زور ځای شوې او تر خولې پورې ډکه ستاسو په لمنه کې واچول شي. ځکه په هره پیمانه چې تاسو یې نورو ته ورکوئ، په هماغه پیمانه به تاسو ته هم درکول کیږي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_38.mp3', '', 1761754199, 1761754199),
(33852, 'Luke 6:39', 'Luke', 6, 39, 'نو عیسی هغوی ته دا مثال ووایه: «ایا یو ړوند بل ړوند ته لاره ښودلی شي؟ ایا دواړه به په کنده کې ونه غورځیږي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_39.mp3', '', 1761754199, 1761754199),
(33853, 'Luke 6:40', 'Luke', 6, 40, 'شاګرد د خپل استاذ څخه لوی نه دی، خو کله چې یو شاګرد خپلې زده کړې پوره کړي، نو د خپل استاذ په شان به شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_40.mp3', '', 1761754199, 1761754199),
(33854, 'Luke 6:41', 'Luke', 6, 41, 'ته ولې د خپل ورور په سترګه کې خسڼی لیدلی شې خو په خپله سترګه کې غټ لرګی لیدلی نه شې؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_41.mp3', '', 1761754199, 1761754199),
(33855, 'Luke 6:42', 'Luke', 6, 42, 'څنګه کولای شې خپل ورور ته ووایې چې ای وروره، اجازه راکړه ستا د سترګې څخه خسڼی وباسم، خو په خپله سترګه کې غټ لرګی لیدلی نه شې؟ ای منافقه! ته باید لومړی د خپلې سترګې څخه لرګی وباسې، بیا کولای شې چې په ښکاره توګه ووینې چې څنګه د خپل ورور د سترګې څخه خسڼی وباسې. ونه د خپلې مېوې څخه پېژندل کیږي (متي ۷‏:‌۱۷‌‏-‌۲۰، ۱۲‏:‌۳۳‌‏-‌۳۵)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_42.mp3', '', 1761754199, 1761754199),
(33856, 'Luke 6:43', 'Luke', 6, 43, 'ښه ونه خرابه مېوه نه نیسي او نه به خرابه ونه ښه مېوه ونیسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_43.mp3', '', 1761754199, 1761754199),
(33857, 'Luke 6:44', 'Luke', 6, 44, 'هره ونه د خپلې مېوې څخه پېژندل کیږي. د اغزو د بوټو څخه انځر او د ځنګلي بوټي څخه انګور نه شئ راټولولی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_44.mp3', '', 1761754199, 1761754199),
(33858, 'Luke 6:45', 'Luke', 6, 45, 'ښه سړی د خپل زړه د ښې خزانې څخه ښه شیان راوباسي او بد سړی د خپل زړه د بدې خزانې څخه بد شیان راوباسي، ځکه کومې خبرې چې په زړه کې وي هغه په خوله راوځي. دوه ډوله بنیادونه (متي ۷‏:‌۲۴‌‏-‌۲۷)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_45.mp3', '', 1761754199, 1761754199),
(33859, 'Luke 6:46', 'Luke', 6, 46, 'تاسو ولې ماته استاذه، استاذه وایئ، خو څه چې درته وایم هغه نه کوئ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_46.mp3', '', 1761754199, 1761754199),
(33860, 'Luke 6:47', 'Luke', 6, 47, 'هرڅوک چې ماته راشي او زما خبرو ته غوږ ونیسي او په هغو باندې عمل وکړي، نو زه به تاسو ته وښایم چې هغه د چا په شان دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_47.mp3', '', 1761754199, 1761754199),
(33861, 'Luke 6:48', 'Luke', 6, 48, 'هغه د یو داسې سړي په شان دی چې د خپل کور د جوړولو دپاره یې ځمکه ښه ژوره کړه او بنیاد یې په تیږو کېښود. کله چې سېلاب راغی او په هغه کور ورغی، خو هغه یې له ځایه ونه شو خوځولی، ځکه چې هغه یې کلک جوړ کړی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_48.mp3', '', 1761754199, 1761754199),
(33862, 'Luke 6:49', 'Luke', 6, 49, 'خو څوک چې زما خبرې اوري او عمل ورباندې نه کوي، نو هغه د هغه سړي په شان دی چې خپل کور یې داسې جوړ کړی ؤ چې بنیاد یې نه ؤ. کله چې په هغه کور باندې سېلاب راغی، نو هغه سمدلاسه راولوېد او بیخي وران شو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke6_verse_49.mp3', '', 1761754199, 1761754199),
(33863, 'Luke 19:1', 'Luke', 19, 1, 'عیسی اریحا ته ننوت او د ښار له منځه تېرېده،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_1.mp3', '', 1761754199, 1761754199),
(33864, 'Luke 19:2', 'Luke', 19, 2, 'نو هلته د زکي په نوم یو سړی ؤ چې د مالیه ټولوونکو مشر او ډېر شتمن ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_2.mp3', '', 1761754199, 1761754199),
(33865, 'Luke 19:3', 'Luke', 19, 3, 'هغه غوښتل وګوري چې عیسی به څنګه سړی وي، خو د هغه قد ډېر ټیټ ؤ او د خلکو د ګڼې‌ګوڼې له امله یې نه شو کولای هغه وویني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_3.mp3', '', 1761754199, 1761754199),
(33866, 'Luke 19:4', 'Luke', 19, 4, 'نو مخکې یې منډه کړه او د چنار ونې ته وخوت، ترڅو عیسی وویني ځکه چې هغه په هغه لاره تېرېده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_4.mp3', '', 1761754199, 1761754199),
(33867, 'Luke 19:5', 'Luke', 19, 5, 'کله چې عیسی هغه ځای ته ورسېده، نو پورته یې وکتل او زکي ته یې وویل: «ای زکي! زر راښکته شه، ځکه چې زه باید نن ستا په کور کې مېلمه شم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_5.mp3', '', 1761754199, 1761754199),
(33868, 'Luke 19:6', 'Luke', 19, 6, 'نو زکي په بیړه راښکته شو او په ډېرې خوشحالۍ سره یې د هغه هرکلی وکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_6.mp3', '', 1761754199, 1761754199),
(33869, 'Luke 19:7', 'Luke', 19, 7, 'کله چې خلکو دا ولیدل، نو په ګورېدلو یې پیل وکړ او ویل یې: «هغه د یو ګناهکار سړي کور ته ورغی چې مېلمه یې شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_7.mp3', '', 1761754199, 1761754199),
(33870, 'Luke 19:8', 'Luke', 19, 8, 'خو زکي ودرېده او عیسی ته یې وویل: «وګوره ښاغلیه! زه مې خپله نیمه شتمني غریبانو ته ورکوم او که د چا څخه مې په ناحقه کوم څه اخیستي وي، نو څلور چنده ورته بېرته ورکوم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_8.mp3', '', 1761754199, 1761754199),
(33871, 'Luke 19:9', 'Luke', 19, 9, 'بیا عیسی وویل: «نن دې کور ته خلاصون راغلی دی، ځکه چې دا سړی هم د ابراهیم د اولادې څخه دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_9.mp3', '', 1761754199, 1761754199),
(33872, 'Luke 19:10', 'Luke', 19, 10, 'ځکه چې د انسان زوی راغلی دی چې ورک شوي ولټوي او هغوی وژغوري.» د لسو نوکرانو مثال (متي ۲۵‏:‌۱۴‌‏-‌۳۰)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_10.mp3', '', 1761754199, 1761754199),
(33873, 'Luke 19:11', 'Luke', 19, 11, 'هغوی د عیسی خبرو ته غوږ نیولی ؤ چې هغه ورته یو بل مثال هم راوړ، ځکه چې هغه اورشلیم ته نژدې ؤ او هغوی ګومان کاوه چې د خدای پاچاهي به همدا‌اوس راښکاره شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_11.mp3', '', 1761754199, 1761754199),
