(33897, 'Luke 19:35', 'Luke', 19, 35, 'او هغوی هغه کوټی عیسی ته راوست، خپلې چپنې یې ورباندې واچولې او عیسی یې ورباندې سپور کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_35.mp3', '', 1761754199, 1761754199),
(33898, 'Luke 19:36', 'Luke', 19, 36, 'کله چې هغه په لاره تللو، نو خلکو خپل کالي ورته په لاره کې غوړول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_36.mp3', '', 1761754199, 1761754199),
(33899, 'Luke 19:37', 'Luke', 19, 37, 'کله چې عیسی هغې لارې ته نژدې شو چې د زیتون د غره څخه راښکته شوې وه، نو ټولو پیروانو یې په خوشحالۍ او لوړ اواز سره د هغو معجزو په خاطر چې هغوی لیدلې وې د خدای د ثنا په ویلو پیل وکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_37.mp3', '', 1761754199, 1761754199),
(33900, 'Luke 19:38', 'Luke', 19, 38, 'او ویل یې: «مبارک دی هغه پاچا چې د څښتن په نوم راځي. سلامتي دې وي په اسمان کې او جلال دې وي څښتن تعالی ته.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_38.mp3', '', 1761754199, 1761754199),
(33901, 'Luke 19:39', 'Luke', 19, 39, 'د خلکو له منځ څخه ځینو فریسیانو عیسی ته وویل: «استاذه! خپلو شاګردانو ته ووایه چې غلي شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_39.mp3', '', 1761754199, 1761754199),
(33902, 'Luke 19:40', 'Luke', 19, 40, 'عیسی په ځواب کې وویل: «زه تاسو ته وایم که هغوی غلي شي، نو تیږې به په چیغو پیل وکړي.» عیسی د اورشلیم په حال ژاړي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_40.mp3', '', 1761754199, 1761754199),
(33903, 'Luke 19:41', 'Luke', 19, 41, 'کله چې عیسی اورشلیم ته نژدې شو او ښار یې ولیده، نو ورته په ژړا شو', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_41.mp3', '', 1761754199, 1761754199),
(33904, 'Luke 19:42', 'Luke', 19, 42, 'او ویې ویل: «کاشکې نن تاته هم د سولې او سلامتۍ لار معلومه وای. خو نه، اوس دا لاره ستا د نظر څخه پټه ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_42.mp3', '', 1761754199, 1761754199),
(33905, 'Luke 19:43', 'Luke', 19, 43, 'ځکه چې داسې ورځې به درباندې راشي چې ستا دښمنان به ستا څخه ګردچاپېره مورچلې جوړې کړي، ستا نه به راتاو شي او د هرې خوا نه به دې را‌ایسار کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_43.mp3', '', 1761754199, 1761754199),
(33906, 'Luke 19:44', 'Luke', 19, 44, 'هغوی به تا او ستا خلک د ځمکې سره هوار کړي او په تا کې به یوه تیږه هم د بلې دپاسه پرېنږدي، ځکه چې تا د خدای د راتللو وخت ونه پېژانده.» عیسی د خدای د کور څخه سوداګران شړي (متي ۲۱‏:‌۱۲‌‏-‌۱۷ او مرقوس ۱۱‏:‌۱۵‌‏-‌۱۹ او یوحنا ۲‏:‌۱۳‌‏-‌۲۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_44.mp3', '', 1761754199, 1761754199),
(33907, 'Luke 19:45', 'Luke', 19, 45, 'کله چې عیسی د خدای کور ته ننوت، نو د هغو خلکو په ویستلو یې پیل وکړ چې هلته یې شیان خرڅول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_45.mp3', '', 1761754199, 1761754199),
(33908, 'Luke 19:46', 'Luke', 19, 46, 'هغوی ته یې وویل: «د خدای په کلام کې لیکل شوي دي: زما کور به د دعا کور وي. خو تاسو ورڅخه د غلو د پټېدلو ځای جوړ کړی دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_46.mp3', '', 1761754199, 1761754199),
(33909, 'Luke 19:47', 'Luke', 19, 47, 'عیسی هره ورځ د خدای په کور کې تعلیم ورکاوه. خو مشرانو کاهنانو، د شریعت عالمانو او قومي مشرانو هڅه کوله چې هغه ووژني،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_47.mp3', '', 1761754199, 1761754199),
(33910, 'Luke 19:48', 'Luke', 19, 48, 'خو هېڅ یې له لاسه پوره نه ؤ، ځکه چې ټولو خلکو په ډېر شوق سره د هغه خبرو ته غوږ نیولی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke19_verse_48.mp3', '', 1761754199, 1761754199);